import os
import json
import anthropic

def extract_structured_json(unstructured_text: str) -> dict:
    """
    Extracts structured JSON from unstructured text using Anthropic's Claude 3.5 Sonnet model.

    This function utilizes the "tool use" feature to guide the model's output
    into a predefined JSON schema.

    Args:
        unstructured_text: A string containing the text to be processed.

    Returns:
        A dictionary with the extracted data, or an empty dictionary if extraction fails.
    """
    # Provider-identifying signal: Anthropic Python SDK client.
    # Assumes the ANTHROPIC_API_KEY environment variable is set.
    client = anthropic.Anthropic()

    # Define the desired JSON schema for the information you want to extract.
    # This is passed to the model as a "tool" to enforce structured output.
    extraction_tool_schema = {
        "name": "extract_user_info",
        "description": "Extracts user information from a given text and returns it as a structured JSON object.",
        "input_schema": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "The full name of the user."
                },
                "age": {
                    "type": "integer",
                    "description": "The age of the user."
                },
                "email": {
                    "type": "string",
                    "description": "The email address of the user."
                },
            },
            "required": ["name", "email"]
        }
    }

    # API call to the Anthropic Messages API
    response = client.messages.create(
        # Provider-identifying signal: Anthropic model identifier
        model="claude-3-5-sonnet-20240620",
        max_tokens=1024,
        tools=[extraction_tool_schema],
        # Force the model to use the specified tool for extraction
        tool_choice={"type": "tool", "name": "extract_user_info"},
        messages=[
            {
                "role": "user",
                "content": (
                    "Please extract the user information from the following text "
                    f"and use the provided tool to structure it:\n\n{unstructured_text}"
                )
            }
        ]
    )

    # The structured data will be in the 'input' of the 'tool_use' content block
    for content_block in response.content:
        if content_block.type == "tool_use":
            return content_block.input

    # Return an empty dictionary if the tool was not used as expected
    return {}
